// Система охраны на Arduino Nano
// ИК-датчик движения, светодиод, зумер

const int PIN_PIR    = 2;   // выход ИК-датчика движения
const int PIN_BUZZER = 8;   // зумер
const int PIN_LED    = 13;  // светодиод (встроенный или внешний)

const int ARM_DELAY_MS   = 5000;  // задержка перед постановкой на охрану (5 сек)
const int ALARM_TIMEOUT  = 10000;  // длительность тревоги (10 сек)
const int DEBOUNCE_MS   = 50;      // защита от дребезга датчика

bool armed = false;       // поставлена ли система на охрану
bool alarm = false;       // активна ли тревога

unsigned long armStart   = 0;
unsigned long alarmStart = 0;
unsigned long lastTrigger = 0;

void setup() {
  Serial.begin(9600);

  pinMode(PIN_PIR, INPUT);
  pinMode(PIN_BUZZER, OUTPUT);
  pinMode(PIN_LED, OUTPUT);

  // Короткий сигнал при включении
  tone(PIN_BUZZER, 1000, 100);
  delay(150);
  tone(PIN_BUZZER, 2000, 100);

  Serial.println("Система запущена. Постановка на охрану через 5 сек...");
}

void loop() {
  unsigned long now = millis();

  // --- Фаза постановки на охрану ---
  if (!armed) {
    // Мигаем светодиодом, показывая что идёт отсчёт
    digitalWrite(PIN_LED, (now / 250) % 2);

    if (now - armStart >= ARM_DELAY_MS) {
      armed = true;
      digitalWrite(PIN_LED, LOW);
      Serial.println("Система поставлена на охрану.");
      // Подтверждающий сигнал
      tone(PIN_BUZZER, 1500, 200);
    }
    return;
  }

  // --- Система на охране ---

  if (alarm) {
    // Тревога: зумер и светодиод работают поочерёдно
    if (now - alarmStart < ALARM_TIMEOUT) {
      // Прерывистый звук и мигание
      bool high = (now / 200) % 2;
      if (high) {
        tone(PIN_BUZZER, 2500);
      } else {
        noTone(PIN_BUZZER);
      }
      digitalWrite(PIN_LED, high);
    } else {
      // Тревога окончена, возвращаемся к дежурному режиму
      alarm = false;
      noTone(PIN_BUZZER);
      digitalWrite(PIN_LED, LOW);
      Serial.println("Тревога сброшена. Система снова на охране.");
    }
    return;
  }

  // --- Дежурный режим: ждём движения ---
  int motion = digitalRead(PIN_PIR);

  if (motion == HIGH && (now - lastTrigger > DEBOUNCE_MS)) {
    lastTrigger = now;
    alarm = true;
    alarmStart = now;
    Serial.println("Тревога! Обнаружено движение!");
  } else {
    // Слабый пульс светодиода — индикация дежурного режима
    int brightness = (sin(now * 0.002) + 1) * 127;
    analogWrite(PIN_LED, brightness);
  }
}
